def shortest_path(graph, start, target):
    queue = deque([(start, [start])])
    visited = set([start])
    while queue:
        vertex, path = queue.popleft()
        if vertex == target:
            return path
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

print(shortest_path(graph, 'A', 'F'))  # ['A', 'C', 'F']

def mean(arr):
    return sum(arr) / len(arr)

def median(arr):
    s = sorted(arr)
    n = len(s)
    if n % 2 == 1:
        return s[n//2]
    return (s[n//2-1] + s[n//2]) / 2

print(mean([1, 2, 3, 4, 5]))  # 3.0
print(median([1, 2, 3, 4, 5]))  # 3

from PIL import Image

def hide_data(image_path, data):
    img = Image.open(image_path)
    pixels = list(img.getdata())
    data_bits = ''.join(format(ord(c), '08b') for c in data) + '11111111'
    new_pixels = []
    for i, pixel in enumerate(pixels):
        if i < len(data_bits):
            r = (pixel[0] & 0xFE) | int(data_bits[i])
            new_pixels.append((r, pixel[1], pixel[2]))
        else:
            new_pixels.append(pixel)
    img.putdata(new_pixels)
    img.save('hidden.png')

def extract_data(image_path):
    img = Image.open(image_path)
    pixels = list(img.getdata())
    bits = ''
    for i, pixel in enumerate(pixels):
        bits += str(pixel[0] & 1)
        if len(bits) % 8 == 0:
            byte = bits[-8:]
            if byte == '11111111':
                break
    text = ''.join(chr(int(bits[i:i+8], 2)) for i in range(0, len(bits)-8, 8))
    return text
